cpp 通过外部中断控制LED开关。当连接到引脚2的按钮/开关状态发生变化时，触发中断服务函数blink()，切换LED（引脚13）的亮灭状态。 const byte ledPin = 13;
const byte interruptPin = 2;
volatile byte state = LOW;

void setup() {
  pinMode(ledPin, OUTPUT);
  pinMode(interruptPin, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(interruptPin), blink, CHANGE);
}

void loop() {
  digitalWrite(ledPin, state);
}

void blink() {
  state = !state;
}

cpp 这是一个Arduino步进电机速度控制函数。通过计算循环时间间隔(dt)，累加脉冲数(pulse2Send)，当累加值达到0.5时执行一步步进操作，并根据正负值决定步进方向。使用微秒级时间戳实现精确的速度控制。 // loop 函数仅用于实现速度控制
void loop() {
  uint32_t currentLoopTime = micros();
  if (inMoving) {
    // 循环之间的间隔
    uint32_t dt = currentLoopTime - lastLoopTime;

    // 角度累加，以脉冲数为单位
    pulse2Send += speedPerPulse * dt;

    // 是否需要步进一格。
    if (abs(pulse2Send) >= 0.5) {
      step(pulse2Send > 0); // 根据方向，步进一格

      // 已完成步进，调整累加值
      if (pulse2Send > 0) {
        pulse2Send -= 1;
      } else {
        pulse2Send += 1;
      }
    }
  }

  lastLoopTime = currentLoopTime;
}

cpp 使用TimerOne库实现定时器中断，每隔1秒切换一次板载LED（LED_BUILTIN）的亮灭状态，实现LED闪烁效果。 #include <TimerOne.h>

void setup() {
  //初始化LED端口
  pinMode(LED_BUILTIN, OUTPUT);

  // 每 1 s 触发一次时间中断
  Timer1.initialize(long(1 * 1E6));

  // 设置中断响应函数
  Timer1.attachInterrupt(LED);

  // 启动时间中断
  Timer1.start();
}

void LED() {
  static bool light = true;

  digitalWrite(LED_BUILTIN, light);
  light = !light;
}
